//! A dishonest prover intended for use in tests.
//!
//! A program is compiled up to its hints, after which some of those hints are replaced and the
//! witness generated by the forged hints is checked against the program's constraint system.

use mavros_artifacts::{InputValueOrdered, MavrosField};

use crate::{
    api,
    compiler::{
        codegen::CodeGenOptions,
        ssa::hlssa::{HLSSA, OpCode},
    },
    driver::Driver,
    vm::interpreter::TrapError,
};

/// Whether `ssa` accepts `inputs` once `forge` has replaced hints in the program witness spilling
/// left, which R1CS generation and code generation both read.
///
/// Refusing is either breaking a constraint or trapping in a range check's helper, whose lookup
/// finds no table row for a value out of range and so refuses that value in the constraints too. A
/// trap anywhere else is no verdict on the forgery, and panics.
pub fn accepts_the_forgery<F: MavrosField>(
    ssa: HLSSA,
    inputs: &[InputValueOrdered<F>],
    forge: impl FnOnce(&mut HLSSA),
) -> bool {
    let dumps = tempfile::TempDir::new().unwrap();
    let mut driver = Driver::from_ssa(ssa, dumps.path().to_path_buf(), false);
    driver.make_struct_access_static().unwrap();
    driver.monomorphize().unwrap();
    driver.spill_witness().unwrap();
    forge(driver.witness_spilled_ssa_mut());

    let r1cs = driver.generate_r1cs::<F>().unwrap();
    let artifact = driver
        .compile_bytecode_artifact(CodeGenOptions {
            check_constraints: false,
            include_debug_info: true,
        })
        .unwrap();
    let mut binary = artifact.binary;
    let witness = match api::run_witgen_from_binary(&mut binary, &r1cs, inputs, artifact.debug_info)
    {
        Ok(witness) => witness,
        Err(trap) if trapped_in_a_range_check(&trap) => return false,
        Err(trap) => panic!("the forgery trapped outside a range check: {trap}"),
    };
    r1cs.unsatisfied_constraint(
        &[
            witness.out_wit_pre_comm.as_slice(),
            witness.out_wit_post_comm.as_slice(),
        ]
        .concat(),
    )
    .is_none()
}

/// Whether `trap` stopped in a range check's helper, which lookup spilling names
/// `__rangecheck_spill_*`. The innermost frame is the first.
fn trapped_in_a_range_check(trap: &TrapError) -> bool {
    trap.stack_trace()
        .first()
        .is_some_and(|frame| frame.function.starts_with("__rangecheck_spill_"))
}

/// Every instruction of `ssa`, cloned, in order.
pub fn all_ops(ssa: &HLSSA) -> impl Iterator<Item = OpCode> {
    ssa.iter_functions()
        .flat_map(|(_, function)| function.get_blocks())
        .flat_map(|(_, block)| block.get_instructions().cloned())
        .collect::<Vec<_>>()
        .into_iter()
}

/// Replaces each instruction `replace` answers for, and counts them.
pub fn replace_hints(ssa: &mut HLSSA, mut replace: impl FnMut(&OpCode) -> Option<OpCode>) -> usize {
    let mut replaced = 0;
    for (_, function) in ssa.iter_functions_mut() {
        for (_, block) in function.get_blocks_mut() {
            for op in block.get_instructions_mut() {
                if let Some(new) = replace(op) {
                    *op = new;
                    replaced += 1;
                }
            }
        }
    }
    replaced
}
